def int_to_str(n):
    return str(n)

def float_to_int(f):
    return int(f)

sample_input = [123, 45.67]

for i, num in enumerate(sample_input):
    if isinstance(num, int):
        print(f"{num} -> {int_to_str(num)}")
    elif isinstance(num, float):
        print(f"{num:.2f} -> {float_to_int(num)}")
    else:
        print(f"Invalid input at index {i}")
